 if(selected==='start')return prefix+scope(starterDistribution({rows,races,lang,data,driver,state,fieldSize:starterFieldSize(rows,races),axisFieldSize:Math.max(20,...data.races.filter(r=>(!state.year||r.year===+state.year)&&(!state.yearMin||r.year>=+state.yearMin)&&(!state.yearMax||r.year<=+state.yearMax)&&(!state.circuit||r.circuit_id===state.circuit)).map(r=>r.drivers||0))}));
 return prefix+scope(`<section class="card quality-detail" id="quality-detail"><h2>${label(selected)}</h2><p>${definitions[selected][index]}</p>${fieldHTML}<div class="chips"><span class="chip">${t('Eigen mediaan per race','Own median across races')}: <b>${score(selected,center)} ${unit(selected)}</b></span><span class="chip">${measured.length} / ${rows.length} ${t('races bruikbaar','usable races')}</span>${ci?`<span class="chip">${t('95%-bootstrapinterval','95% bootstrap interval')}: ${format(ci[0],3)} ${t('tot','to')} ${format(ci[1],3)} ${unit(selected)}</span>`:`<span class="chip">${t('Minder dan vijf races: geen onzekerheidsinterval','Fewer than five races: no uncertainty interval')}</span>`}</div>${selected==='start'?`<p class="note">${t('Het resultaat is lokale relatieve positiewinst, geen telling van inhaalacties.','This is local relative position gain, not an overtake count.')}</p>`:''}<label class="quality-race-label">${t('Grafiek','Chart')}<select id="quality-race"><option value="">${t('Alle bruikbare races','All usable races')}</option>${measured.map(x=>`<option value="${esc(x.row.race)}" ${x.row.race===state.qualityrace?'selected':''}>${races.get(x.row.race).year} · ${esc(races.get(x.row.race).name)}</option>`).join('')}</select></label>${chart()}<details class="quality-method"><summary>${t('Berekening en interpretatie','Calculation and interpretation')}</summary><p>${methods[selected][index]}</p>${selected!=='start'?`<p>${t('Datadekking binnen de geselecteerde races','Coverage within the selected races')}: ${coverage.timed_laps} ${t('rondetijden','lap times')} · ${coverage.clean_laps} ${t('bruikbare droge ronden met bekende set en leeftijd','usable dry laps with known set and age')} · ${coverage.free_laps} ${t('met gemeten vrije-luchtindicatie','with measured clear-air indication')} · ${coverage.paired_laps} ${t('geaccepteerde gekoppelde ronden','accepted paired laps')}.</p>`:''}<p>${t('Eerste ronde, pit-/uitronden, bronwaarschuwingen, regenbanden en neutralisaties worden voor de tempometingen uitgesloten. Bandenleeftijd is de leeftijd vóór de lopende ronde. De racewaarde is de mediaan van geaccepteerde sets of vensters, daarna telt iedere race eenmaal. Het 95%-interval bij de eigen meting gebruikt 800 hersteekproeven van volledige races; herhaalde omstandigheden en dezelfde tegenstanders kunnen afhankelijkheid geven.','Lap one, pit/out laps, source warnings, wet tyres and neutralisations are excluded from pace measurements. Tyre age is the age before the current lap. The race value is the median of accepted sets or windows, then each race contributes once. The 95% interval for the own measurement uses 800 bootstrap resamples of whole races; repeated conditions and the same opponents may introduce dependence.')}</p><p>${t('Hier staan de eigen waarden en verdelingen. Bij vrije-baantempo en bandenbehoud is de teamgenoot de rekenkundige referentie; bij opwarming en pitvensters de eigen stinttrend. Zichtbare vergelijkingen met andere coureurs staan in GOAT. Verschillen in auto, verkeer, schade en opdrachten blijven mogelijk. Een lege meting is onbekend, geen nul.','These are own values and distributions. Clear-air pace and tyre retention use the teammate as a reference; warm-up and pit windows use the own stint trend. Visible comparisons with other drivers live in GOAT. Car, traffic, damage and team instructions may still differ. An empty measurement is unknown, not zero.')}</p></details></section>`);
